import { z } from "zod";
import { VerifierRefSchema } from "./task-contract";
import { newUuid } from "./uuid";

// Cycle/run/attempt/execution ids are opaque. A session epoch is instead a persisted provider-session
// generation; an occurrence key identifies the routine and due instant independently of retries.

const Id = z.string().min(1).max(200);

export const CycleIdSchema = Id.brand<"CycleId">();
export const RunIdSchema = Id.brand<"RunId">();
export const AttemptIdSchema = Id.brand<"AttemptId">();
/** Generated by Bots so it survives host events that carry no turn id or repeat one. */
export const ExecutionIdSchema = Id.brand<"ExecutionId">();
/** Persisted provider-session generation. Zero means unknown/unopened, never an observed historical session. */
export const SessionEpochSchema = z
  .number()
  .int()
  .nonnegative()
  .max(Number.MAX_SAFE_INTEGER)
  .brand<"SessionEpoch">();
/** What the host reported for the turn. Evidence only: `(agentId, turnId)` is not a safe key to dedupe on. */
export const ProviderTurnIdSchema = Id.brand<"ProviderTurnId">();
/** One due occurrence of a routine, the same across retries. */
export const OccurrenceKeySchema = Id.brand<"OccurrenceKey">();
/** One requested change, so a repeated request can be told from a new one. */
export const OperationIdSchema = Id.brand<"OperationId">();

export type CycleId = z.infer<typeof CycleIdSchema>;
export type RunId = z.infer<typeof RunIdSchema>;
export type AttemptId = z.infer<typeof AttemptIdSchema>;
export type ExecutionId = z.infer<typeof ExecutionIdSchema>;
export type SessionEpoch = z.infer<typeof SessionEpochSchema>;
export type ProviderTurnId = z.infer<typeof ProviderTurnIdSchema>;
export type OccurrenceKey = z.infer<typeof OccurrenceKeySchema>;
export type OperationId = z.infer<typeof OperationIdSchema>;

const generated = (prefix: string) => `${prefix}-${newUuid()}`;

export const newCycleId = (): CycleId => CycleIdSchema.parse(generated("cyc"));
export const newRunId = (): RunId => RunIdSchema.parse(generated("run"));
export const newAttemptId = (): AttemptId => AttemptIdSchema.parse(generated("att"));
export const newExecutionId = (): ExecutionId => ExecutionIdSchema.parse(generated("exe"));
/** Advance the persisted generation at a provider-session boundary, not at plugin startup. */
export function newSessionEpoch(previous: number = 0): SessionEpoch {
  return SessionEpochSchema.parse(SessionEpochSchema.parse(previous) + 1);
}
export const newOperationId = (): OperationId => OperationIdSchema.parse(generated("op"));

export const providerTurnId = (turnId: string | null | undefined): ProviderTurnId | null =>
  turnId ? ProviderTurnIdSchema.parse(turnId) : null;

export const TRIGGERS = ["schedule", "manual", "webhook"] as const;
export type Trigger = (typeof TRIGGERS)[number];

/**
 * A scheduled run is keyed by routine and due instant, so a retry of the same occurrence has the same key.
 * A manual or webhook run has no due instant to repeat, so each request is its own occurrence.
 */
export function occurrenceKeyOf(
  routineId: string,
  trigger: string,
  dueIso: string,
  runId: string,
): OccurrenceKey {
  return OccurrenceKeySchema.parse(
    trigger === "schedule" ? `${routineId}@${dueIso}` : `${routineId}#${runId}`,
  );
}

/** Why a turn exists. Set when the chat is created, never guessed from its prompt. */
export const PURPOSES = ["task", "memory_review", "evaluation", "maintenance"] as const;
export const PurposeSchema = z.enum(PURPOSES);
export type Purpose = z.infer<typeof PurposeSchema>;

/** Carries a chat's purpose. */
export const PURPOSE_LABEL = "paseo-bots.purpose";

/**
 * A chat made before purposes existed has no label and is a task. A label this version didn't write is
 * unknown (null), and an unknown purpose is never eligible for anything.
 */
export function purposeFromLabels(
  labels: Readonly<Record<string, string>> | null | undefined,
): Purpose | null {
  const raw = labels?.[PURPOSE_LABEL];
  if (raw === undefined) return "task";
  const parsed = PurposeSchema.safeParse(raw);
  return parsed.success ? parsed.data : null;
}

export const EXECUTION_STATUSES = [
  "queued",
  "reserved",
  "starting",
  "running",
  "waiting_for_user",
  "verifying",
  "completed",
  "failed",
  "canceled",
  "unknown",
] as const;
/** What the execution did, said by the host or by Bots; never whether the task's goal was met. */
export const ExecutionStatusSchema = z.enum(EXECUTION_STATUSES);
export type ExecutionStatus = z.infer<typeof ExecutionStatusSchema>;

/** Agent creation evidence is independent of whether the task needed or achieved a change. */
export const AgentCreationStatusSchema = z.enum(["not_created", "created", "unknown"]);
export type AgentCreationStatus = z.infer<typeof AgentCreationStatusSchema>;

const TERMINAL: Record<ExecutionStatus, boolean> = {
  queued: false,
  reserved: false,
  starting: false,
  running: false,
  waiting_for_user: false,
  verifying: false,
  completed: true,
  failed: true,
  canceled: true,
  unknown: true,
};

/** `unknown` is terminal in the sense that nothing here will change it; a later reconcile may. */
export const isTerminal = (status: ExecutionStatus): boolean => TERMINAL[status];

export const TASK_OUTCOMES = [
  "verified_success",
  "verified_failure",
  "needs_review",
  "unknown",
  "no_change",
] as const;
export const TaskOutcomeSchema = z.enum(TASK_OUTCOMES);
export type TaskOutcome = z.infer<typeof TaskOutcomeSchema>;

/** Which pinned verifier judged the result, and when. Only a verification can make an outcome verified. */
export const VerificationSchema = z.object({ verifier: VerifierRefSchema, at: z.string() });
export type Verification = z.infer<typeof VerificationSchema>;

export interface RunState {
  executionStatus: ExecutionStatus;
  taskOutcome: TaskOutcome;
  verification: Verification | null;
}

/** Null when the pair can be true. A model saying it succeeded is not a verification. */
export function runStateIssue({ executionStatus, taskOutcome, verification }: RunState): string | null {
  const verified = taskOutcome === "verified_success" || taskOutcome === "verified_failure";
  if (verified && !verification) return `${taskOutcome} needs a verification`;
  if (!verified && verification) return `${taskOutcome} can't carry a verification`;
  if (verified && executionStatus !== "completed") return `${taskOutcome} needs a completed execution`;
  if (!isTerminal(executionStatus) && taskOutcome !== "unknown")
    return `${executionStatus} runs have no outcome yet`;
  return null;
}

/** What an ended turn says about the execution. Its outcome stays unknown until something verifies it. */
export function settleTurn(
  kind: "completed" | "failed" | "canceled",
): Pick<RunState, "executionStatus" | "taskOutcome"> {
  return { executionStatus: kind, taskOutcome: "unknown" };
}

/** Runs saved before the two facts were split. `succeeded` meant only that the turn completed. */
export const LEGACY_RUN_STATUSES = [
  "running",
  "succeeded",
  "failed",
  "skipped-busy",
  "skipped-missed",
] as const;
export type LegacyRunStatus = (typeof LEGACY_RUN_STATUSES)[number];

export const SKIPPED = ["busy", "missed"] as const;
export const SkippedSchema = z.enum(SKIPPED);
export type Skipped = z.infer<typeof SkippedSchema>;

export interface RunDisposition extends Pick<RunState, "executionStatus" | "taskOutcome"> {
  skipped: Skipped | null;
}

/**
 * The old label never says the task worked, so a completed turn keeps an unknown outcome. A skipped run
 * never launched, so it changed nothing. Anything this version doesn't know is an unknown execution.
 */
export function fromLegacyStatus(status: unknown): RunDisposition {
  switch (status) {
    case "running":
      return { executionStatus: "running", taskOutcome: "unknown", skipped: null };
    case "succeeded":
      return { executionStatus: "completed", taskOutcome: "unknown", skipped: null };
    case "failed":
      return { executionStatus: "failed", taskOutcome: "unknown", skipped: null };
    case "skipped-busy":
      return { executionStatus: "canceled", taskOutcome: "no_change", skipped: "busy" };
    case "skipped-missed":
      return { executionStatus: "canceled", taskOutcome: "no_change", skipped: "missed" };
    default:
      return { executionStatus: "unknown", taskOutcome: "unknown", skipped: null };
  }
}

export type RunTone = "success" | "warning" | "error" | "muted";

/**
 * One label for every surface. Green is reserved for a verified success: a finished turn is not a
 * working task, and an outcome nobody checked says so.
 */
export function describeRun(run: RunDisposition): { label: string; tone: RunTone } {
  if (run.skipped === "busy") return { label: "Skipped, still working", tone: "muted" };
  if (run.skipped === "missed") return { label: "Missed", tone: "warning" };
  switch (run.executionStatus) {
    case "queued":
      return { label: "Queued", tone: "muted" };
    case "reserved":
    case "starting":
      return { label: "Starting", tone: "muted" };
    case "running":
      return { label: "Running", tone: "muted" };
    case "waiting_for_user":
      return { label: "Waiting for you", tone: "warning" };
    case "verifying":
      return { label: "Verifying", tone: "muted" };
    case "failed":
      return { label: "Failed", tone: "error" };
    case "canceled":
      return run.taskOutcome === "unknown"
        ? { label: "Stopped, effects unknown", tone: "warning" }
        : { label: "Stopped", tone: "muted" };
    case "unknown":
      return { label: "Outcome unknown", tone: "warning" };
    case "completed":
      return completedLabel(run.taskOutcome);
  }
}

function completedLabel(outcome: TaskOutcome): { label: string; tone: RunTone } {
  switch (outcome) {
    case "verified_success":
      return { label: "Verified success", tone: "success" };
    case "verified_failure":
      return { label: "Verified failure", tone: "error" };
    case "needs_review":
      return { label: "Completed, needs review", tone: "warning" };
    case "no_change":
      return { label: "Completed, no change", tone: "muted" };
    case "unknown":
      return { label: "Completed, not verified", tone: "muted" };
  }
}

/**
 * Only a terminal task cycle that ran to a conclusion belongs in a review window. Maintenance, memory
 * review and evaluation turns would otherwise be reviewed as the work they were checking, and a stopped
 * or unknown one has no conclusion to learn from.
 */
export function isReviewEligible({
  purpose,
  executionStatus,
}: {
  purpose: Purpose | null;
  executionStatus: ExecutionStatus;
}): boolean {
  return purpose === "task" && (executionStatus === "completed" || executionStatus === "failed");
}
